public struct FfiConverterTypeMobileEvent: FfiConverterRustBuffer {
    typealias SwiftType = MobileEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connecting
        
        case 2: return .connected(transport: try FfiConverterString.read(from: &buf), agent: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .disconnected(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .transcript(role: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf), isFinal: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .reply(text: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .error(message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .audioChunk(data: try FfiConverterData.read(from: &buf), sampleRate: try FfiConverterUInt32.read(from: &buf), done: try FfiConverterBool.read(from: &buf)
        )
        
        case 8: return .channelList(channels: try FfiConverterSequenceTypeChannelListItem.read(from: &buf)
        )
        
        case 9: return .channelEvents(channelId: try FfiConverterString.read(from: &buf), events: try FfiConverterSequenceTypeChannelEventItem.read(from: &buf)
        )
        
        case 10: return .channelUpdate(channelId: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MobileEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .connecting:
            writeInt(&buf, Int32(1))
        
        
        case let .connected(transport,agent):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(transport, into: &buf)
            FfiConverterString.write(agent, into: &buf)
            
        
        case let .disconnected(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .transcript(role,text,isFinal):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(role, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterBool.write(isFinal, into: &buf)
            
        
        case let .reply(text):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .error(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .audioChunk(data,sampleRate,done):
            writeInt(&buf, Int32(7))
            FfiConverterData.write(data, into: &buf)
            FfiConverterUInt32.write(sampleRate, into: &buf)
            FfiConverterBool.write(done, into: &buf)
            
        
        case let .channelList(channels):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceTypeChannelListItem.write(channels, into: &buf)
            
        
        case let .channelEvents(channelId,events):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(channelId, into: &buf)
            FfiConverterSequenceTypeChannelEventItem.write(events, into: &buf)
            
        
        case let .channelUpdate(channelId):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(channelId, into: &buf)
            
        }
    }
