 * Foreign-implemented sink for [`MobileEvent`]s. Swift/Kotlin provide this.
 */
public protocol MobileEventListener: AnyObject, Sendable {
    
    func onEvent(event: MobileEvent) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMobileEventListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMobileEventListener = UniffiVTableCallbackInterfaceMobileEventListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceMobileEventListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface MobileEventListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceMobileEventListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface MobileEventListener: handle missing in uniffiClone")
            }
        },
        onEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceMobileEventListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     event: try FfiConverterTypeMobileEvent_lift(event)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceMobileEventListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceMobileEventListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitMobileEventListener() {
    uniffi_mur_mobile_sdk_fn_init_callback_vtable_mobileeventlistener(UniffiCallbackInterfaceMobileEventListener.vtablePtr)
}

